def swap_count(s):
    """Write a function to find out the minimum no of swaps required for bracket balancing in the given string."""
    count_left = 0
    count_right = 0
    imbalance = 0
    swaps = 0
    for ch in s:
        if ch == '[':
            count_left += 1
            if imbalance > 0:
                swaps += imbalance
                imbalance -= 1
        elif ch == ']':
            count_right += 1
            imbalance = count_right - count_left
    return swaps
